import logging
from ta_attenuator.config_loader import ConfigLoader
from ta_attenuator.config_loader import WrongSyntaxInConfigurationFile
from ta_attenuator.attenuators_impls.jfw import JfwAttenuator
from ta_attenuator.attenuators_impls.test import TestAttenuator
from ta_attenuator.attenuators_impls.hytem import HytemAttenuator
from ta_attenuator.attenuators_impls.radiorack import RadioRackAttenuator
from ta_attenuator.cell import Cell


class ConfigParser(object):
    """Module reading configuration and creating attenuators and cells"""

    SUPPORTED_ATTENUATORS = ['test', 'jfw', 'hytem', 'radiorack', 'haojin', 'topyoung']

    def __init__(self, config_path, attenuators_pool, cells_pool):
        self.confg_loader = ConfigLoader(config_path)
        self.configuration = self.confg_loader.load_config()
        self.attenuators_pool = attenuators_pool
        self.cells_pool = cells_pool

    def load_attenuators(self):
        """
        Load attenuators from configuration file
        """
        try:
            for attenuator in self.configuration['ATTENUATORS']:
                att_type = self.configuration['ATTENUATORS'][attenuator]['TYPE']
                self._validate_type(att_type.lower())
                self._register_jfw_attenuator(att_type.lower(), attenuator)
                self._register_hytem_attenuator(att_type.lower(), attenuator)
                self._register_radiorack_attenuator(att_type.lower(), attenuator)
                self._register_test_attenuator(att_type.lower(), attenuator)
        except KeyError:
            raise WrongSyntaxInConfigurationFile("Probably mistake in your configuration file. Please check the syntax again.")

    def _validate_type(self, att_type):
        if att_type not in self.SUPPORTED_ATTENUATORS:
            raise AttenuatorTypeNotSupported("Supported attenuator types = {}".format(str(self.SUPPORTED_ATTENUATORS)))

    def _validate_mode(self, mode):
        if mode not in ['ports', 'blocks']:
            raise AttenuatorModeNotSupported("Supported attenuator modes = {}".format(str(['ports', 'blocks'])))

    def _register_radiorack_attenuator(self, att_type, attenuator):
        if att_type in self.SUPPORTED_ATTENUATORS and att_type == 'radiorack':
            ip, port, max_att, min_att = self._read_att_details(attenuator)
            ip = self.configuration['ATTENUATORS'][attenuator]['CONSTRUCTOR_PARAMETERS']['ip']
            port = self.configuration['ATTENUATORS'][attenuator]['CONSTRUCTOR_PARAMETERS']['port']
            logging.debug('Found attenuator {} with IP {}'.format(attenuator, ip))
            self.attenuators_pool.register_attenuator(attenuator, RadioRackAttenuator(min_att, max_att, ip, port))

    def _register_jfw_attenuator(self, att_type, attenuator):
        if att_type in self.SUPPORTED_ATTENUATORS and att_type == 'jfw' or att_type == 'topyoung':
            ip, port, max_att, min_att = self._read_att_details(attenuator)
            mode = self._read_jfw_mode(attenuator)
            self._validate_mode(mode)
            logging.debug('Found attenuator {} with IP {}'.format(attenuator, ip))
            self.attenuators_pool.register_attenuator(attenuator, JfwAttenuator(min_att, max_att, ip, port, mode))

    def _read_jfw_mode(self, attenuator):
        mode = self.configuration['ATTENUATORS'][attenuator]['CONSTRUCTOR_PARAMETERS'].get('mode', 'ports')
        return str(mode).lower()

    def _register_test_attenuator(self, att_type, attenuator):
        if att_type in self.SUPPORTED_ATTENUATORS and att_type == 'test':
            ip, port, max_att, min_att = self._read_att_details(attenuator)
            logging.debug('Found test attenuator {} with IP {} and port {}'.format(attenuator, ip, port))
            self.attenuators_pool.register_attenuator(attenuator, TestAttenuator(min_att, max_att))

    def _read_att_details(self, attenuator):
        ip = self.configuration['ATTENUATORS'][attenuator]['CONSTRUCTOR_PARAMETERS']['ip']
        port = self.configuration['ATTENUATORS'][attenuator]['CONSTRUCTOR_PARAMETERS']['port']
        max_att = self.configuration['ATTENUATORS'][attenuator]['CONSTRUCTOR_PARAMETERS']['max_attenuation']
        min_att = self.configuration['ATTENUATORS'][attenuator]['CONSTRUCTOR_PARAMETERS']['min_attenuation']
        if max_att <= min_att:
            raise ValueError("Wrong min and max attenuation values set for {}. Minimal value {} is greater than"
                             " or equal to maximal {}".format(attenuator, min_att, max_att))
        return ip, port, max_att, min_att

    def _register_hytem_attenuator(self, att_type, attenuator):
        if att_type in self.SUPPORTED_ATTENUATORS and att_type == 'hytem':
            ip = self.configuration['ATTENUATORS'][attenuator]['CONSTRUCTOR_PARAMETERS']['ip']
            max_att = self.configuration['ATTENUATORS'][attenuator]['CONSTRUCTOR_PARAMETERS']['max_attenuation']
            min_att = self.configuration['ATTENUATORS'][attenuator]['CONSTRUCTOR_PARAMETERS']['min_attenuation']
            logging.debug('Found attenuator {} with IP {}'.format(attenuator, ip))
            self.attenuators_pool.register_attenuator(attenuator, HytemAttenuator(min_att, max_att, ip))

    def load_cells(self):
        """
        Load cells from configuration file
        """
        try:
            logging.debug(self.configuration['CELLS_ATTENUATION'])
            for cell in self.configuration['CELLS_ATTENUATION']:
                self._create_cell(cell, self.configuration['CELLS_ATTENUATION'][cell]['rf_paths_of_cell'])
        except KeyError:
            raise WrongSyntaxInConfigurationFile("Probably mistake in your configuration file. Please check the syntax again.")

    def _create_cell(self, cell, cell_config_list):
        used_att = []
        for cell_att_dict in cell_config_list:
            used_att.append(cell_att_dict['used_attenuator'])
        self.cells_pool.register_cell(cell, Cell(cell, used_att, cell_config_list))


class AttenuatorTypeNotSupported(Exception):
    """Exception raised when given attenuator is not supported"""
    pass


class AttenuatorModeNotSupported(Exception):
    """Exception raised when given attenuator mode is not supported"""
    pass
